    transport_costs = [[3.58, 4.67, 1.57, 4.2, 3.96, 1.49, 1.57], [3.22, 3.71, 4.7, 3.15, 1.8, 1.21, 1.62], [1.24, 4.11, 4.77, 4.89, 2.75, 1.18, 3.96], [2.8, 3.08, 1.78, 3.46, 3.72, 4.26, 2.58], [1.67, 1.63, 1.11, 2.85, 1.1, 2.29, 3.81], [4.27, 3.37, 2.69, 1.18, 2.19, 4.91, 5.0], [4.35, 4.7, 4.22, 2.26, 1.57, 3.24, 4.28], [2.94, 4.02, 3.11, 2.12, 2.35, 2.59, 3.67], [4.0, 3.37, 4.42, 2.03, 4.23, 1.37, 2.94], [1.1, 4.95, 1.58, 2.56, 2.59, 3.65, 3.59]]
    risk_costs = [[65.83, 141.92, 63.31, 175.77, 129.82, 77.3, 88.03], [197.44, 173.0, 138.09, 105.96, 57.86, 78.7, 77.05], [123.7, 169.85, 97.2, 138.19, 197.03, 69.41, 128.71], [60.24, 65.49, 130.86, 131.75, 182.24, 164.15, 186.61], [130.29, 82.61, 162.13, 178.91, 103.03, 137.92, 145.12], [195.71, 127.97, 133.94, 111.4, 59.46, 73.15, 73.21], [65.69, 63.19, 143.73, 116.89, 119.06, 128.24, 170.88], [87.97, 138.76, 58.25, 85.86, 120.87, 58.37, 189.31], [85.83, 57.42, 149.26, 85.55, 134.21, 67.13, 146.23], [88.61, 124.11, 136.42, 74.96, 90.26, 172.8, 87.77]]
